<?php require_once __DIR__.'/../config/bootstrap.php'; if(current_user()) redirect('aluno/area.php'); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$senha=$_POST['senha']??'';$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($senha,$u['senha']))$err='E-mail ou senha inválidos.';elseif($u['status']!=='active')$err='Sua conta está bloqueada. Procure o administrador.';else{login_user((int)$u['id']);if(!empty($_POST['lembrar']))remember_login((int)$u['id']);flash('success','Login realizado.');$dest=$_SESSION['after_login']??($u['role']==='admin'?'admin/index.php':'aluno/area.php');unset($_SESSION['after_login']);if(str_starts_with($dest,'/')){header('Location: '.$dest);exit;}redirect($dest);}} ?>
